"use strict";(self.webpackChunkapp=self.webpackChunkapp||[]).push([[85],{1072:function(e,t,a){a.d(t,{n:function(){return c},Z:function(){return h}});a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p;var i=a.p+"static/media/walter_sisulu.dba959f5686843484833.png",n=a.p+"static/media/orlando_towers.4c6867777a2cca29b0a7.png",o=a.p+"static/media/melville_koppies.59396b48b6f2a616015b.png",s=a.p+"static/media/truth_club.b7b59e9d315539b85036.png",r=a.p+"static/media/kitcheners.d7bd020192823dc2892c.png",l=a.p+"static/media/rhino_lion.ae50be4c218c56c4b181.png",h=(a.p,a.p,a.p,a.p,a.p,a.p,a.p,a.p,[{id:1,img:i,title:"Walter Sisulu Botanical Garden",location:"Roodepoort, Johannesburg",googleMapsUrl:"https://goo.gl/maps/WalterSisulu",description:"The Walter Sisulu National Botanical Garden is a 300-hectare paradise established in 1982. Its crown jewel is the 70-meter Witpoortjie Waterfall, which has been a popular recreational spot since the late 1800s. The garden consists of various natural vegetation types, including Northern Afrotemperate Forest and Gold Reef Mountain Bushveld.\n\nMore than just a garden, it's a critical conservation site. It is famously home to a breeding pair of Verreaux's (Black) Eagles, Makatsa and Mahlori, who nest on the cliffs adjacent to the waterfall. They are the only known pair of these majestic raptors in an urban environment. Visitors can spend hours exploring themed sections like the Geological Garden, the Succulent Rockery, or the Bird and Butterfly Garden.",startDate:"Available Year-round",endDate:"Best in Summer",category:"Nature",readTime:"5 min read",rating:4.9,tags:["Nature","Waterfall","Eagles"],highlights:["Witpoortjie Waterfall (70m)","Verreaux's Eagles nesting site","Geological Garden trail","Eagle's Fare Tea Garden"],gallery:["https://images.unsplash.com/photo-1590641121063-441634676602","https://images.unsplash.com/photo-1548199973-03cce0bbc87b","https://images.unsplash.com/photo-1518335031952-475306660fac"]},{id:2,img:n,title:"Orlando Towers Bungee",location:"Soweto, Johannesburg",googleMapsUrl:"https://goo.gl/maps/OrlandoTowers",description:"Transformed from the remnants of the Orlando Power Station, these iconic mural-covered cooling towers have become the heartbeat of adventure in Soweto. The bungee jump takes place from a suspension bridge slung 100 meters above the ground, offering a heart-stopping 33-storey freefall.\n\nBeyond the jump, the towers are a cultural landmark. The massive murals celebrate the history and vibrancy of Soweto. If you're not ready for the bungee, you can try the SCAD Free Fall\u2014internal to the tower\u2014or the Power Swing. The views from the top provide a breathtaking 360-degree panorama of the township's vast urban landscape and the distant JHB city skyline.",startDate:"Book in Advance",endDate:"Daily 10am - 6pm",category:"Active",readTime:"4 min read",rating:5,tags:["Bungee","Soweto","Adrenaline"],highlights:["100m Bridge Bungee Jump","SCAD Free Fall experience","Vibrant heritage murals","Soweto panoramic views"],gallery:["https://images.unsplash.com/photo-1571171637578-41bc2dd4dcd2","https://images.unsplash.com/photo-1549141070-529a657c664b","https://images.unsplash.com/photo-1517457373958-b7bdd4587205"]},{id:3,img:o,title:"Melville Koppies Hike",location:"Emmarentia, Johannesburg",googleMapsUrl:"https://goo.gl/maps/MelvilleKoppies",description:"Melville Koppies is a Nature Reserve and Johannesburg City Heritage Site that serves as a living window into Earth's history. Its geological roots date back three billion years. Walking here feels like stepping back in time; stone tools discovered on the ridges prove that Early Stone Age people camped here 500,000 years ago.\n\nThe reserve is partitioned into Central, East, and West sections. The Central section is a preservation marvel, containing an excavated Iron-Age smashing furnace from about 600 years ago. On Sunday mornings, guided tours offer insights into the indigenous flora, archaeology, and the sheer resilience of this highveld ridge against the backdrop of a modernizing city.",startDate:"Guided Tours Sundays",endDate:"East/West open daily",category:"History",readTime:"6 min read",rating:4.8,tags:["Hiking","History","Skyline"],highlights:["Iron-Age smelting furnace","3-billion-year-old rock formations","Indigenous Highveld flora","Sunday Heritage walks"],gallery:["https://images.unsplash.com/photo-1523712999610-f77fbcfc3843","https://images.unsplash.com/photo-1514330188214-388e635832a8","https://images.unsplash.com/photo-1464822759023-fed622ff2c3b"]},{id:4,img:s,title:"Truth Night Club",location:"Midrand, Johannesburg",googleMapsUrl:"https://goo.gl/maps/TruthClub",description:"Truth is South Africa's longest-running electronic music club, a legendary venue that has shaped the country's dance culture for decades. Known as the 'Home of the Underground,' it features multiple dance floors, each with its own sonic personality, from dark techno bunkers to open-air terraces.\n\nThe atmosphere is electric, fueled by state-of-the-art lighting and sound systems that rival international festivals. Truth regularly hosts world-class local and international DJs, drawing a diverse, high-energy crowd. It is a destination for those who seek more than just a party\u2014it is an immersive electronic music experience that often lasts until the early morning light.",startDate:"Weekends Only",endDate:"Late Night to Dawn",category:"Vibes",readTime:"5 min read",rating:4.7,tags:["Nightlife","Techno","Underground"],highlights:["The Terrace (Electronic hub)","Multiple immersive dance floors","International DJ sets","Festival-grade sound system"],gallery:["https://images.unsplash.com/photo-1516450360452-9312f5e86fc7","https://images.unsplash.com/photo-1470225620780-dba8ba36b745","https://images.unsplash.com/photo-1514525253361-b83f85df6f5c"]},{id:5,img:r,title:"Kitchener's Carvery Bar",location:"Braamfontein, Johannesburg",googleMapsUrl:"https://goo.gl/maps/Kitcheners",description:"Established in 1906, Kitchener's is one of Johannesburg's oldest operating pubs, located in a building that predates the turn of the century. Originally the Milner Park Hotel, it has witnessed the city's transformation from a mining camp into a metropolis.\n\nIn 2009, Kitchener's was reimagined as a cultural institution, blending its vintage wooden interiors and etched glass with the cutting-edge energy of Braamfontein's youth. During the day, it's a quiet spot for a carvery meal; by night, it explodes into a vibrant dance floor. It's known for its inclusive atmosphere where students, creatives, and regulars mingle to the sounds of indie rock, Afro-beat, and deep house.",startDate:"Open Daily",endDate:"Great Vibes Always",category:"Vibes",readTime:"6 min read",rating:4.9,tags:["Vintage","Braam","Dance"],highlights:["1906 historic pub interior","Milner Park Hotel architecture","Inclusive 'Braam' community","Eclectic live DJ sets"],gallery:["https://images.unsplash.com/photo-1514933651103-005eec06c04b","https://images.unsplash.com/photo-1551024709-8f23befc6f87","https://images.unsplash.com/photo-1559339352-11d035aa65de"]},{id:6,img:l,title:"Rhino & Lion Nature Reserve",location:"Cradle of Humankind, JHB",googleMapsUrl:"https://goo.gl/maps/RhinoLion",description:"Situated in the UNESCO World Heritage Site of the Cradle of Humankind, this 1200-hectare reserve offers a wildlife experience just a short drive from the city. It is home to over 30 species, including white rhinos, lions (both brown and white), cheetahs, and the endangered African wild dog.\n\nThe reserve focus is on conservation and education. Visitors can explore via self-drive or guided game drives. One of the unique features is the Wonder Cave, an enchanting underground cavern with massive stalactites and stalagmites. There is also a vulture hide, allowing rare close-up views of Cape Vultures in their natural habitat.",startDate:"Open Daily",endDate:"Morning Safaris Best",category:"Nature",readTime:"7 min read",rating:4.8,tags:["Safari","Wildlife","Big Cats"],highlights:["Wonder Cave guided tour","White & Brown Lion prides","Vulture Hide observation","African Wild Dog enclosure"],gallery:["https://images.unsplash.com/photo-1546182990-dffeafbe841d","https://images.unsplash.com/photo-1553284965-83fd3e10fa6c","https://images.unsplash.com/photo-1563294520-29c8e4ea3e38"]},{id:7,img:"https://images.unsplash.com/photo-1549141070-529a657c664b",title:"Apartheid Museum",location:"Ormonde, Johannesburg",googleMapsUrl:"https://goo.gl/maps/ApartheidMuseum",description:"The Apartheid Museum is a powerful and essential landmark that documents South Africa's transition from institutionalized racial segregation to democracy. Opened in 2001, its architecture is intentionally brutalist, using raw concrete and steel bars to evoke the feeling of oppression and confinement.\n\nVisitors are guided through 22 individual exhibition areas on a journey from 'Darkness to Hope.' The experience is visceral, beginning with a random racial classification at the entrance. The museum's collection of dramatic photography, personal artifacts, and footage provides a comprehensive look at the rise and fall of apartheid, acting as a solemn place of reflection and a testament to the human spirit's fight for freedom.",startDate:"Open Tue - Sun",endDate:"Allow 3+ hours",category:"Culture",readTime:"8 min read",rating:4.9,tags:["History","Culture","Educate"],highlights:["Simulated segregation entrance","Wall of the Gallows","1976 Soweto Uprising exhibit","Mandela: Leader and Hero gallery"],gallery:["https://images.unsplash.com/photo-1549417229-aa67d3263c93","https://images.unsplash.com/photo-1516627145497-ae6968895b74","https://images.unsplash.com/photo-1506744038136-46273834b3fb"]}]),c=[{id:101,img:i,title:"A Sunday Morning at Walter Sisulu",location:"Roodepoort",description:"Nothing beats the peace of the Botanical Gardens on a crisp Sunday morning. As we walked through the Succulent Rockery, the sun was just starting to hit the red cliffs of the Zwartkop ridge. We headed straight for the Witpoortjie Waterfall, and to our absolute luck, Mahlori (the male black eagle) was circling the air currents right above the falls.\n\nIt was a moment of pure serenity in the middle of our busy city. We eventually set up our picnic blanket near the stream. Pro tip for locals: bring a good pair of binoculars and maybe a bird book; there's so much more to see than just the eagles! It's the perfect reset for the week ahead.",startDate:"March 2024",category:"Nature",author:"Thabo M.",readTime:"4 min read"},{id:102,img:n,title:"Facing my Fears in Soweto",location:"Soweto",description:"Standing at the edge of the suspension bridge between the two Orlando Towers, my heart was actually in my throat. The wind was whipping around us, and Soweto looked like a sprawling colorful map below. I've lived in Joburg all my life, but I've never seen it from this perspective.\n\nThe safety crew were incredible\u2014calm, professional, and full of jokes to ease the tension. When I finally made the leap, the freefall was the most terrifying and exhilarating 5 seconds of my life. Bouncing back up and seeing those massive murals up close was surreal. If you're looking for an adrenaline kick, this is the gold standard.",startDate:"February 2024",category:"Active",author:"Sarah J.",readTime:"6 min read"},{id:103,img:r,title:"Braam Vibes: A Night at Kitchener's",location:"Braamfontein",description:"The music, the people, the history. Kitchener's is more than just a bar; it's the heart of the Braam pulse. We started the night with some quiet drinks in the vintage booths, surrounded by the etched glass and wood that's been there since 1906. But as 'Golden Hour' faded, the energy shifted entirely.\n\nThe dance floor filled up within minutes, the air getting heavy with the bass of a deep house set. What I love most about this place is how it feels like a true cultural melting pot\u2014students, artists, and old-timers all sharing the same space. It's raw, it's authentic, and it's quintessentially Johannesburg.",startDate:"January 2024",category:"Vibes",author:"Lebo G.",readTime:"5 min read"}]},4132:function(e,t,a){var i=a(9439),n=a(2791),o=a(7132),s=a(484),r=a(184);t.Z=function(e){var t=e.defaultSticky,a=(0,n.useState)(t||!1),l=(0,i.Z)(a,2),h=l[0],c=l[1],d=(0,n.useState)(!1),p=(0,i.Z)(d,2),u=p[0],g=p[1],m=(0,o.TH)();(0,n.useEffect)((function(){if(!t){var e=function(){c(window.scrollY>80)};return window.addEventListener("scroll",e),function(){return window.removeEventListener("scroll",e)}}}),[t]);var f=[{name:"Home",path:"/"},{name:"Gallery",path:"/gallery"},{name:"Explore",path:"/explore"},{name:"Blog",path:"/blog"}];return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)("nav",{className:"navbar ".concat(h?"sticky":""," ").concat(u?"drawer-open":""),children:[(0,r.jsxs)(o.rU,{to:"/",className:"navbar-brand",children:[(0,r.jsx)(s.vcW,{}),(0,r.jsx)("span",{children:"Trip Tips"})]}),(0,r.jsx)("div",{className:"navlist",children:(0,r.jsx)("ul",{children:f.map((function(e){return(0,r.jsx)("li",{className:"navitem",children:(0,r.jsx)(o.rU,{to:e.path,className:"nav-link ".concat(m.pathname===e.path?"active":""),children:e.name})},e.name)}))})}),(0,r.jsx)("div",{className:"mobile-toggle",onClick:function(){return g(!u)},children:u?(0,r.jsx)(s.IOM,{}):(0,r.jsx)(s.lIk,{})})]}),(0,r.jsx)("div",{className:"mobile-drawer ".concat(u?"open":""),children:(0,r.jsx)("div",{className:"drawer-content",children:(0,r.jsx)("ul",{children:f.map((function(e){return(0,r.jsx)("li",{onClick:function(){return g(!1)},children:(0,r.jsx)(o.rU,{to:e.path,className:m.pathname===e.path?"active":"",children:e.name})},e.name)}))})})}),u&&(0,r.jsx)("div",{className:"drawer-overlay",onClick:function(){return g(!1)}})]})}}}]);
